export function studioBuddy(mood='ready',size=88){const faces={ready:'<path d="M37 48v8m17-8v8"/><path d="M41 65q5 4 10-1"/>',quiet:'<path d="M36 52h5m12 0h5"/><path d="M43 65h8"/>',done:'<path d="M35 52q4-6 8 0m8 0q4-6 8 0"/><path d="M43 64q5 6 10-1"/>',notice:'<path d="M37 48v8m17-8v8"/><path d="M45 65h3"/>'};return `<svg class="studio-buddy" width="${Number.isFinite(size)?size:88}" height="${Number.isFinite(size)?size:88}" viewBox="0 0 96 96" fill="none" aria-hidden="true" focusable="false"><ellipse cx="49" cy="86" rx="28" ry="4" fill="#ece9e7"/><path d="M25 24 72 20 80 77 34 83Z" fill="#ffdce2"/><path d="M22 21Q21 15 28 15L65 12 76 25 80 73Q81 79 74 80L30 84Q25 85 24 78Z" fill="#fffdfa" stroke="#292524" stroke-width="2" stroke-linejoin="round"/><path d="m65 12 1 16 10-3" fill="#ff2442" stroke="#292524" stroke-width="2" stroke-linejoin="round"/><path d="m32 28 17-2" stroke="#ff2442" stroke-width="3" stroke-linecap="round"/><g stroke="#292524" stroke-width="4" stroke-linecap="round">${faces[mood]||faces.ready}</g><path d="m19 64-6 5m64-9 7 3M35 84l-2 5m28-7 3 6" stroke="#292524" stroke-width="2.5" stroke-linecap="round"/><circle cx="29" cy="60" r="3" fill="#ffb7c3"/><path d="m8 29 5-2m-1-6 2 4M83 37l4-1" stroke="#f04461" stroke-width="2" stroke-linecap="round"/></svg>`;}
export function navigationIcon(index=0){const paths=['<rect x="4" y="4" width="16" height="16" rx="4"/><path d="M4 10h16m-10 0v10"/>','<rect x="4" y="5" width="16" height="15" rx="3"/><path d="m8 5 1-2h6l1 2m-8 7h8m-8 4h5"/>','<path d="M4 8h16v12H4zM3 4h18v4H3zm6 8h6"/>','<path d="M12 5C8 2 4 4 3 5v14c4-2 7-1 9 1 3-2 6-3 9-1V5c-3-2-7-2-9 0zm0 0v15"/>','<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2m1-15a3 3 0 0 1 0 6m3 9v-2a6 6 0 0 0-2-5"/>','<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 10h18m-6 5h3M6 5V3"/>','<path d="m12 3 3 2 4 1 1 4-1 4-3 3-4 3-4-3-3-3-1-4 1-4 4-1z"/><circle cx="12" cy="11" r="3"/>'];return `<svg class="navigation-icon" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[index%paths.length]}</svg>`;}
